                        <span aria-disabled="true" aria-label="{{ __('pagination.previous') }}">
                            <span class="relative inline-flex items-center px-3 py-2 text-sm font-bold text-gray-400 bg-slate-100 border-r-2 border-border-solid cursor-not-allowed" aria-hidden="true">
                                <i class="fa-solid fa-chevron-left"></i>
