                    @else
                        <a href="{{ $paginator->previousPageUrl() }}" rel="prev" class="relative inline-flex items-center px-3 py-2 text-sm font-bold text-text-onsurface bg-white border-r-2 border-border-solid hover:bg-slate-100 hover:text-primary transition-colors focus:z-10 focus:outline-none" aria-label="{{ __('pagination.previous') }}">
                            <i class="fa-solid fa-chevron-left"></i>
                        </a>
