                    {{-- Next Page Link --}}
                    @if ($paginator->hasMorePages())
                        <a href="{{ $paginator->nextPageUrl() }}" rel="next" class="relative inline-flex items-center px-3 py-2 text-sm font-bold text-text-onsurface bg-white hover:bg-slate-100 hover:text-primary transition-colors focus:z-10 focus:outline-none" aria-label="{{ __('pagination.next') }}">
